{"HelperA.dfy": "O1.Certify(m, k, j);
    O2.SwapKeys(m, k, j);
    var m1 := K.Swap(m, k, j);
    O1.Certify(m1, k, j);
    O2.SwapKeys(m1, k, j);
    forall q | q in m ensures q in K.Swap(m1, k, j) && K.Swap(m1, k, j)[q] == m[q] {
      O2.SwapAt(m, k, j, q);
      O2.SwapAt(m1, k, j, q);
    }
    A.Equal(K.Swap(m1, k, j), m);", "HelperB.dfy": "O1.Certify(m, k, j);
    O2.SwapKeys(m, k, j);
    var m1 := K.Swap(m, k, j);
    O1.Certify(m1, k, j);
    O2.SwapKeys(m1, k, j);
    forall q | q in m ensures q in K.Swap(m1, k, j) && K.Swap(m1, k, j)[q] == m[q] {
      O2.SwapAt(m, k, j, q);
      O2.SwapAt(m1, k, j, q);
    }
    A.Equal(K.Swap(m1, k, j), m);"}

